ValidationRule.errorConditionFormula:
AND(
    ISPICKVAL(Status__c, "Registered"),
    OR(
        AND(
            OR(ISPICKVAL(Booking__r.Funding_Type__c, "Home Loan"), ISPICKVAL(Booking__r.Funding_Type__c, "Part Self + Part Loan"), ISPICKVAL(Booking__r.Funding_Type__c, "Loan")),
            OR(NOT(DD_Uploaded__c), ISBLANK(DD_Reference__c), NOT(Legal_Approval__c))
        ),
        AND(
            OR(ISPICKVAL(Booking__r.Funding_Type__c, "Self Payment"), ISPICKVAL(Booking__r.Funding_Type__c, "Self-Funded")),
            OR(Booking__r.Pending_Dues__c > 0, Booking__r.Is_Locked__c, NOT(Legal_Approval__c))
        )
    )
)
